INSERT INTO units(id,project_id,number,track_id,state,title,created_by_user,approved_revision,approved_at,created_at,updated_at) SELECT ('00000000-0000-0000-0000-'||lpad((1000+n)::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000010',n,'00000000-0000-0000-0000-000000000003','queued','Report é😀 '||n,'00000000-0000-0000-0000-000000000001',1,'2001-01-01Z','2001-01-01Z','2001-01-01Z' FROM generate_series(1,9)n;
INSERT INTO attempts(id,project_id,unit_id,sequence,state,unit_revision,science_revision,track_id,claimed_by_user,via_channel,lease_generation,claimed_at,started_at,finished_at,origin,source_ref,imported) SELECT ('00000000-0000-0000-0000-'||lpad((2000+n)::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000010',('00000000-0000-0000-0000-'||lpad((1000+n)::text,12,'0'))::uuid,1,CASE WHEN n=7 THEN 'failed' ELSE 'verified' END,2,3,'00000000-0000-0000-0000-000000000004','00000000-0000-0000-0000-000000000001','historical',0,'2001-01-01Z',CASE WHEN n<8 THEN '2001-01-02Z'::timestamptz END,CASE WHEN n<7 THEN '2001-01-03Z'::timestamptz END,CASE WHEN n>=6 THEN 'imported' ELSE 'live' END,CASE WHEN n>=6 THEN 'archive:'||n END,CASE WHEN n>=6 THEN '{"wide":123456789012345678901234567890,"fraction":1.5}'::jsonb END FROM generate_series(1,9)n;
INSERT INTO phase_outputs(id,project_id,attempt_id,stage,status,revision,front_matter,sha256,producer_user,producer_service,via_channel,created_at) SELECT ('00000000-0000-0000-0000-'||lpad((3000+n)::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000010',('00000000-0000-0000-0000-'||lpad((2000+n)::text,12,'0'))::uuid,'agent',CASE WHEN n=2 THEN 'failed' ELSE 'completed' END,1,'{"report":{"what_was_tried":"Try é😀","configuration":"Fixture configuration","observations":"Observed é😀","findings":"{\"x\":[null,true,1.0,123456789012345678901234567890]}","limitations":"Synthetic fixture","next_question":"Does retrieval improve?","elapsed_seconds":1.25,"body_markdown":"# Report"},"measurements":[{"value":1.25,"sample_count":123456789012345678901234567890,"authority":"agent_claim","dimensions":{"slice":"é😀"},"metric":"score","split":"test","unit":"fraction","direction":"higher"}]}',repeat('a',64),CASE WHEN n<>2 THEN '00000000-0000-0000-0000-000000000002'::uuid END,CASE WHEN n=2 THEN '00000000-0000-0000-0000-000000000020'::uuid END,'api','2001-02-03T04:05:06.123456Z' FROM generate_series(1,4)n;
