INSERT INTO phase_outputs(id,project_id,attempt_id,stage,status,revision,front_matter,body,sha256,via_channel,via_client,created_at,origin,source_ref) SELECT ('00000000-0000-0000-0000-'||lpad((8000+n)::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000010',('00000000-0000-0000-0000-'||lpad((2000+n)::text,12,'0'))::uuid,'writeup','completed',1,jsonb_strip_nulls(jsonb_build_object('kind','retrospective','author','History é😀','written_on',CASE WHEN n=6 THEN '1999-12-31'::date END,'written_at',CASE WHEN n=7 THEN '2000-01-01T02:03:04.123456Z'::timestamptz END)),'# Historical report',repeat('e',64),'cli','cannery import','2001-01-01Z','imported','reports/history-'||n FROM generate_series(6,7)n;
